using System;using System.IO;using System.Diagnostics;using System.Security.Principal;using System.Web.Script.Serialization;using ThinkPadModesV3;
internal static class ZeroQualification {
 static int ElevateCap(string report){try{var p=Process.Start(new ProcessStartInfo(typeof(ZeroQualification).Assembly.Location,"--cap \""+report+"\""){UseShellExecute=true,Verb="runas",WindowStyle=ProcessWindowStyle.Hidden});p.WaitForExit();File.WriteAllText(report+".launcher.json",new JavaScriptSerializer().Serialize(new{ExitCode=p.ExitCode}));return p.ExitCode;}catch(Exception e){File.WriteAllText(report+".launcher.json",e.Message);return 1;}}
 static int Cap(string report){if(!new WindowsPrincipal(WindowsIdentity.GetCurrent()).IsInRole(WindowsBuiltInRole.Administrator))return 77;var rows=new System.Collections.Generic.List<object>();bool success=false;string error=null;try{if(!WindowsPower.OnMains())throw new IOException("AC required");CoolingClient.Send("set","Auto");using(var lease=new ZeroPowerLease(report+".lease.json")){for(int i=0;i<120;i++){if(!lease.Verified)throw new IOException("CPU limits changed externally");var r=PipeClient.Send("status");if(!r.Ok)throw new IOException(r.Error);var selected=new System.Collections.Generic.Dictionary<string,object>();foreach(string key in new[]{"CpuPackage","CpuPackageMsr","GpuTemperature","CpuWatts"}){var v=r.Snapshot.Sensors[key];if(v.Status!="valid"||!v.Value.HasValue|| (DateTime.UtcNow-DateTime.Parse(v.AcquiredUtc).ToUniversalTime()).TotalMilliseconds>4500)throw new IOException("Stale sensor");selected[key]=v.Value.Value;if((key.Contains("Package")&&v.Value>=75)||(key=="GpuTemperature"&&v.Value>=60))throw new IOException("Thermal abort");}var fans=CoolingClient.Send("status");if(!fans.Ok||fans.Snapshot.Faulted)throw new IOException("RPM service unavailable");rows.Add(new{UTC=DateTime.UtcNow.ToString("o"),Sensors=selected,Fans=fans.Snapshot});System.Threading.Thread.Sleep(1000);}}success=true;}catch(Exception e){error=e.Message;}File.WriteAllText(report,new JavaScriptSerializer().Serialize(new{UTC=DateTime.UtcNow.ToString("o"),Success=success,Error=error,FanCommands="Auto only",PL1Watts=8,PL2Watts=8,Boost=0,Samples=rows,LeaseRestored=!File.Exists(report+".lease.json")}));return success?0:1;}
 public static int Main(string[] args){if(args.Length!=2)return 64;string report=Path.GetFullPath(args[1]);if(args[0]=="--elevate-cap")return ElevateCap(report);if(args[0]=="--cap")return Cap(report);if(args[0]=="--elevate-read"){try{var p=Process.Start(new ProcessStartInfo(typeof(ZeroQualification).Assembly.Location,"--read \""+report+"\""){UseShellExecute=true,Verb="runas",WindowStyle=ProcessWindowStyle.Hidden});p.WaitForExit();File.WriteAllText(report+".launcher.json",new JavaScriptSerializer().Serialize(new{ExitCode=p.ExitCode}));return p.ExitCode;}catch(Exception e){File.WriteAllText(report+".launcher.json",new JavaScriptSerializer().Serialize(new{Error=e.Message}));return 1;}}
 if(args[0]!="--read"||!new WindowsPrincipal(WindowsIdentity.GetCurrent()).IsInRole(WindowsBuiltInRole.Administrator))return 77;
 try{LenovoOemTransport.Verify();using(var m=new PawnModule("IntelMSR.bin")){ulong units=m.Execute("ioctl_read_msr",0x606),limit=m.Execute("ioctl_read_msr",0x610),info=m.Execute("ioctl_read_msr",0x614);double pu=Math.Pow(0.5,(int)(units&15));File.WriteAllText(report,new JavaScriptSerializer().Serialize(new{UTC=DateTime.UtcNow.ToString("o"),Success=true,ReadOnly=true,Units=units.ToString("X16"),Limit=limit.ToString("X16"),Info=info.ToString("X16"),Lock=(limit>>63)!=0,PL1=(limit&32767)*pu,PL2=((limit>>32)&32767)*pu,PL1Enabled=(limit&0x8000)!=0,PL2Enabled=(limit&0x800000000000)!=0,PowerUnit=pu}));}return 0;}catch(Exception e){File.WriteAllText(report,new JavaScriptSerializer().Serialize(new{Success=false,Error=e.Message}));return 1;}
 }
}
